package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.JSONObject;import java.util.*;
/** Public UI + Activity.dump only: exercises the actual minified Release, no test keep rules. */
public class NavigationMotionInstrumentation extends Instrumentation {
 int maxHomeCommitsPerMove;Activity a;android.content.SharedPreferences prefs;Map<String,?> saved;StringBuilder report=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 JSONObject nav(){StringWriterHolder h=new StringWriterHolder();runOnMainSync(()->a.dump("",null,new java.io.PrintWriter(h.s),null));for(String line:h.s.toString().split("\n"))if(line.startsWith("NextTVNavigation "))try{return new JSONObject(line.substring(17));}catch(Exception e){throw new RuntimeException(e);}throw new IllegalStateException("No nav diagnostics");}
 static class StringWriterHolder{java.io.StringWriter s=new java.io.StringWriter();}
 void await(String label,java.util.concurrent.Callable<Boolean> f)throws Exception{long end=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<end){if(f.call())return;SystemClock.sleep(35);}throw new IllegalStateException(label);}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String s){if(n==null)return null;if(s.contentEquals(n.getText()==null?"":n.getText()))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=find(n.getChild(i),s);if(r!=null)return r;}return null;}
 void key(int k){sendKeyDownUpSync(k);SystemClock.sleep(80);}
 boolean focusedHas(AccessibilityNodeInfo n,String text){if(n==null)return false;if(n.isFocused())return has(n,text);for(int i=0;i<n.getChildCount();i++)if(focusedHas(n.getChild(i),text))return true;return false;}
 boolean has(AccessibilityNodeInfo n,String text){if(n==null)return false;if(n.getText()!=null&&n.getText().toString().contains(text))return true;for(int i=0;i<n.getChildCount();i++)if(has(n.getChild(i),text))return true;return false;}
 void toggle()throws Exception{for(int i=0;i<35;i++){if(focusedHas(getUiAutomation().getRootInActiveWindow(),"界面动效")){key(KeyEvent.KEYCODE_DPAD_CENTER);SystemClock.sleep(250);return;}key(KeyEvent.KEYCODE_DPAD_DOWN);}throw new IllegalStateException("Cannot reach motion setting with D-pad");}
 void pass(String s){report.append("PASS ").append(s).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+s+"\n");sendStatus(0,b);}
 List<Float> move(boolean off)throws Exception{
 List<Float> xs=new java.util.concurrent.CopyOnWriteArrayList<>();List<Integer> roots=new java.util.concurrent.CopyOnWriteArrayList<>();ViewTreeObserver.OnDrawListener listener=()->{try{java.io.StringWriter s=new java.io.StringWriter();a.dump("",null,new java.io.PrintWriter(s),null);for(String line:s.toString().split("\n"))if(line.startsWith("NextTVNavigation ")){JSONObject frame=new JSONObject(line.substring(17));xs.add((float)frame.getDouble("x"));roots.add(frame.getInt("homeCompositions"));if(frame.getDouble("scale")!=1d)throw new IllegalStateException("Capsule changed scale");}}catch(Exception e){throw new RuntimeException(e);}};
 runOnMainSync(()->a.getWindow().getDecorView().getViewTreeObserver().addOnDrawListener(listener));sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);await("immediate selected tab",()->nav().getInt("tab")==1);SystemClock.sleep(650);runOnMainSync(()->a.getWindow().getDecorView().getViewTreeObserver().removeOnDrawListener(listener));JSONObject n=nav();float target=(float)n.getDouble("target");if(Math.abs(n.getDouble("x")-target)>1)throw new IllegalStateException("Capsule did not settle "+n);if(n.getBoolean("motionOff")!=off)throw new IllegalStateException("Switch not applied");if(off){for(float x:xs)if(x>.5f&&x<target-.5f)throw new IllegalStateException("OFF still interpolates "+xs);}else if(new HashSet<Float>(xs).size()<3)throw new IllegalStateException("ON capsule missing animation "+xs);if(!roots.isEmpty())maxHomeCommitsPerMove=Math.max(maxHomeCommitsPerMove,java.util.Collections.max(roots)-java.util.Collections.min(roots));if(maxHomeCommitsPerMove>4)throw new IllegalStateException("Home recomposes with animation frames "+roots);return xs;}
 JSONObject grid(){StringWriterHolder h=new StringWriterHolder();runOnMainSync(()->a.dump("",null,new java.io.PrintWriter(h.s),null));for(String line:h.s.toString().split("\n"))if(line.startsWith("NextTVGrid "))try{return new JSONObject(line.substring(11));}catch(Exception e){throw new RuntimeException(e);}throw new IllegalStateException("No grid diagnostics");}
 void dragWithoutInertia()throws Exception{
  key(KeyEvent.KEYCODE_DPAD_LEFT);SystemClock.sleep(300);long down=SystemClock.uptimeMillis();for(int i=0;i<=13;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==13?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float y=540f-i*25f;MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,850f,y,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(e,true);e.recycle();SystemClock.sleep(12);}
  SystemClock.sleep(50);JSONObject first=grid();SystemClock.sleep(300);JSONObject last=grid();if(first.getInt("first")==0&&first.getInt("offset")==0)throw new IllegalStateException("Direct touch drag did not move content");if(first.getInt("first")!=last.getInt("first")||first.getInt("offset")!=last.getInt("offset"))throw new IllegalStateException("OFF retained fling "+first+" -> "+last);pass("motion OFF keeps direct touch scrolling but no release-time inertia");key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);key(KeyEvent.KEYCODE_DPAD_RIGHT);
 }
 void constantSizeOnReturn()throws Exception{
  key(KeyEvent.KEYCODE_DPAD_LEFT);SystemClock.sleep(600);JSONObject before=nav();List<String> shapes=new java.util.concurrent.CopyOnWriteArrayList<>();ViewTreeObserver.OnDrawListener listener=()->{try{java.io.StringWriter s=new java.io.StringWriter();a.dump("",null,new java.io.PrintWriter(s),null);for(String line:s.toString().split("\n"))if(line.startsWith("NextTVNavigation ")){JSONObject f=new JSONObject(line.substring(17));if(f.getDouble("scale")!=1d||Math.abs(f.getDouble("width")-before.getDouble("width"))>.1||f.getDouble("height")!=46d)throw new IllegalStateException("Return resized capsule "+f);shapes.add(f.getDouble("width")+"x"+f.getDouble("height"));}}catch(Exception e){throw new RuntimeException(e);}};
  runOnMainSync(()->a.getWindow().getDecorView().getViewTreeObserver().addOnDrawListener(listener));try{key(KeyEvent.KEYCODE_DPAD_DOWN);SystemClock.sleep(300);key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(600);}finally{runOnMainSync(()->a.getWindow().getDecorView().getViewTreeObserver().removeOnDrawListener(listener));}if(shapes.isEmpty())throw new IllegalStateException("No rendered return frames");pass("focus leaves content and returns with constant capsule width/height/scale across "+shapes.size()+" draws");
 }
 void restore(){if(a!=null)runOnMainSync(()->a.finish());if(saved==null)return;android.content.SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> x:saved.entrySet()){Object v=x.getValue();String k=x.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);}e.commit();}
 @Override public void onStart(){int code=Activity.RESULT_OK;try{
 prefs=getTargetContext().getSharedPreferences("nexttv",0);saved=new HashMap<>(prefs.getAll());prefs.edit().putBoolean("start_live",false).putBoolean("reduce_motion",false).commit();a=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("Home ready",()->find(getUiAutomation().getRootInActiveWindow(),"频道")!=null);SystemClock.sleep(1000);
 pass("motion ON capsule uses intermediate rendered positions and settles: "+move(false));key(KeyEvent.KEYCODE_DPAD_RIGHT);SystemClock.sleep(500);toggle();if(!prefs.getBoolean("reduce_motion",false))throw new IllegalStateException("UI switch failed to save OFF");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);SystemClock.sleep(300);pass("UI switch OFF snaps capsule without intermediate positions: "+move(true));dragWithoutInertia();key(KeyEvent.KEYCODE_DPAD_RIGHT);SystemClock.sleep(300);key(KeyEvent.KEYCODE_DPAD_DOWN);toggle();if(prefs.getBoolean("reduce_motion",true))throw new IllegalStateException("UI switch failed to save ON");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);SystemClock.sleep(500);pass("UI switch ON restores capsule immediately without restart: "+move(false));
 for(int i=0;i<8;i++){key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_LEFT);}SystemClock.sleep(600);JSONObject n=nav();if(n.getInt("tab")!=1||Math.abs(n.getDouble("x")-n.getDouble("target"))>1)throw new IllegalStateException("Queued nav "+n);pass("repeated right/left retargets current capsule without queued transitions");constantSizeOnReturn();pass("render-layer animation isolated from Home; maximum home commit span per move="+maxHomeCommitsPerMove);
 }catch(Throwable t){code=Activity.RESULT_CANCELED;report.append(android.util.Log.getStackTraceString(t));}finally{restore();}Bundle b=new Bundle();b.putString("stream",report.toString());finish(code,b);}
}
